def n(v,d=3):return '—' if v is None else f'{v:.{d}f}'.replace('.',',')
def table(head,rows):return '\n'.join(['|'+'|'.join(head)+'|','|'+'|'.join('---' for _ in head)+'|']+['|'+'|'.join(str(v) for v in row)+'|' for row in rows])+'\n'
